record.field:
# Scope to clinic staff only — avoids contaminating Purchase / Accounting routing.
launcher = env['ir.actions.client'].search([('tag', '=', 'afia_app_launcher')], limit=1)
count = 0
if launcher:
    group_ids = []
    for ref in ['afia_dental_core.group_clinic_admin',
                'afia_dental_core.group_clinic_dentist',
                'afia_dental_core.group_clinic_receptionist',
                'afia_dental_core.group_clinic_assistant']:
        try:
            group_ids.append(env.ref(ref).id)
        except Exception:
            pass
    domain = [('share', '=', False), ('active', '=', True)]
    if group_ids:
        domain.append(('groups_id', 'in', group_ids))
    users = env['res.users'].search(domain)
    users.write({'action_id': launcher.id})
    count = len(users)
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'App Launcher Applied',
        'message': '✓ Home action set for %d internal users.' % count,
        'type': 'success',
        'sticky': False,
        'next': {'type': 'ir.actions.act_window_close'},
    },
}
